    <div class="joystick-area"><div id="joystick" class="joystick" aria-label="移動用仮想スティック"><span class="dpad up">⌃</span><span class="dpad down">⌄</span><span class="dpad left">‹</span><span class="dpad right">›</span><div id="stick-knob">${H(`target`)}</div></div><span>MOVE</span></div>
